// Function to calculate the n-th Fibonacci number
pub fn fib(n: u32) -> u64 {
    // Base cases
    if n == 0 {
        return 0;
    } else if n == 1 {
        return 1;
    }

    // Recursive case: F(n) = F(n-1) + F(n-2)
    let mut a = 0;
    let mut b = 1;
    for _ in 2..=n {
        let next = a + b;
        a = b;
        b = next;
    }
    next
}

