/// Encodes a string into run-length encoding.
/// Each run of equal characters is represented as a count followed by the character.
/// An empty string results in an empty string.
///
/// # Examples
///
/// ```
/// assert_eq!(rle("aaabcc"), "3a1b2c");
/// assert_eq!(rle(""), "");
/// ```
fn rle(input: &str) -> String {
    if input.is_empty() {
        return String::new();
    }

    let mut encoded = String::new();
    let mut current_char = input.chars().next().unwrap();
    let count = 1;

    for c in input.chars() {
        if c == current_char {
            count += 1;
        } else {
            encoded.push_str(&format!("{}{}", count, current_char));
            count = 1;
            current_char = c;
        }
    }

    encoded.push_str(&format!("{}{}", count, current_char));

    encoded
}

// Check function to verify the correctness of the `rle` function
fn check() {
    assert_eq!(rle("aaabcc"), "3a1b2c");
    assert_eq!(rle(""), "");
    assert_eq!(rle("aabbcc"), "3a2b2c");
    assert_eq!(rle("abc"), "3a1b2c");
    assert_eq!(rle("aaa"), "3a1b1c");
    assert_eq!(rle("a"), "1a");
    assert_eq!(rle("aabb"), "3a2b2");
    assert_eq!(rle("abcc"), "3a1b2c");
    assert_eq!(rle("abcde"), "3a1b2c3d4e");
    println!("All tests passed!");
}

