// Import necessary packages
use std::collections::HashMap;

/// Counts the occurrences of each word in a given text.
/// Words are considered to be separated by whitespace and are case-insensitive.
///
/// # Examples
///
/// ```
/// assert_eq!(word_count("Hello World"), HashMap::from([(String::from("hello"), 1), (String::from("world"), 1)]));
/// assert_eq!(word_count("Rust Programming"), HashMap::from([(String::from("rust"), 1), (String::from("programming"), 1)]));
/// ```
fn word_count(text: &str) -> HashMap<String, usize> {
    let mut word_map = HashMap::new();
    let words: Vec<&str> = text.split_whitespace().collect();
    for word in words {
        let lower_word = word.to_lowercase();
        *word_map.entry(lower_word).or_insert(0) += 1;
    }
    word_map
}

// Function to check the correctness of the word_count function
fn check() {
    assert_eq!(word_count("Hello World"), HashMap::from([(String::from("hello"), 1), (String::from("world"), 1)]));
    assert_eq!(word_count("Rust Programming"), HashMap::from([(String::from("rust"), 1), (String::from("programming"), 1)]));
    println!("All tests passed successfully!");
}

