/// Computes the least common multiple (LCM) of two non-negative integers `a` and `b`.
/// If either `a` or `b` is 0, the result is 0.
///
/// # Examples
///
/// ```
/// assert_eq!(lcm(4, 6), 12);
/// assert_eq!(lcm(21, 6), 42);
/// assert_eq!(lcm(0, 6), 0);
/// assert_eq!(lcm(0, 0), 0);
/// ```
fn lcm(a: u64, b: u64) -> u64 {
    if a == 0 || b == 0 {
        0
    } else {
        (a / gcd(a, b)) * b
    }
}

fn gcd(a: u64, b: u64) -> u64 {
    while b != 0 {
        let temp = b;
        b = a % b;
        a = temp;
    }
    a
}

