use std::str::SplitWhitespace;

/// Reverses the words in a given string and separates them by spaces.
///
/// # Examples
///
/// ```
/// assert_eq!(reverse_words(String::from("Hello World")), String::from("World Hello"));
/// assert_eq!(reverse_words(String::from("Rust Programming")), String::from("Programming Rust"));
/// ```
fn reverse_words(s: &str) -> String {
    let words: Vec<&str> = s.split_whitespace().collect();
    words.reverse();
    words.join(" ")
}

// Function to check the correctness of the reverse_words function
fn check_reverse_words() {
    assert_eq!(reverse_words(String::from("Hello World")), String::from("World Hello"));
    assert_eq!(reverse_words(String::from("Rust Programming")), String::from("Programming Rust"));
    assert_eq!(reverse_words(String::from("")), String::from(""));
    assert_eq!(reverse_words(String::from("One Two Three")), String::from("Three Two One"));
    println!("All tests passed successfully!");
}

