/// Determines if two strings are anagrams of each other, ignoring case and spaces.
///
/// # Examples
///
/// ```
/// assert_eq!(is_anagram("listen", "silent"), true);
/// assert_eq!(is_anagram("hello", "billion"), false);
/// assert_eq!(is_anagram("apple", "pale"), true);
/// assert_eq!(is_anagram("apple", "pale"), false);
/// ```
fn is_anagram(a: &str, b: &str) -> bool {
    // Remove spaces and convert to lowercase for case-insensitive comparison
    let cleaned_a = a.chars().filter(|c| !c.is_whitespace()).collect::<Vec<char>>();
    let cleaned_b = b.chars().filter(|c| !c.is_whitespace()).collect::<Vec<char>>();

    // Sort the characters of both strings and compare
    cleaned_a.sort_unstable();
    cleaned_b.sort_unstable();

    cleaned_a == cleaned_b
}

