/// Calculates the sum of the decimal digits of a given non-negative integer.
///
/// # Examples
///
/// ```
/// assert_eq!(sum_digits(12345), 15);
/// assert_eq!(sum_digits(98765), 45);
/// ```
fn sum_digits(n: u64) -> u32 {
    let mut sum = 0;
    while n > 0 {
        sum += n % 10;
        n /= 10;
    }
    sum
}

// Function to check the correctness of the `sum_digits` function
fn check() {
    assert_eq!(sum_digits(12345), 15);
    assert_eq!(sum_digits(98765), 45);
    assert_eq!(sum_digits(14789), 45);
    assert_eq!(sum_digits(0), 0);
    assert_eq!(sum_digits(11111111), 55);
    println!("All tests passed successfully!");
}

