/// Finds the index of a target value in a sorted slice.
/// Returns the index of the target if found, otherwise None.
///
/// # Examples
///
/// ```
/// assert_eq!(find(&[1, 2, 3, 4, 5], 3), Some(2));
/// assert_eq!(find(&[1, 2, 3, 4, 5], 6), None);
/// ```
fn find(v: &[i32], target: i32) -> Option<usize> {
    let mut left = 0;
    let mut right = v.len() - 1;

    while left <= right {
        let mid = left + (right - left) / 2;

        match v[mid] {
            target => Some(mid),
            _ => {
                if target < v[mid] {
                    right = mid - 1;
                } else {
                    left = mid + 1;
                }
            }
        }
    }

    None
}

// A simple check function to verify the correctness of the `find` function.
fn check() {
    assert_eq!(find(&[1, 2, 3, 4, 5], 3), Some(2));
    assert_eq!(find(&[1, 2, 3, 4, 5], 6), None);
    assert_eq!(find(&[10, 20, 30, 40, 50], 30), Some(2));
    assert_eq!(find(&[10, 20, 30, 40, 50], 40), Some(3));
    assert_eq!(find(&[10, 20, 30, 40, 50], 50), Some(4));
    assert_eq!(find(&[10, 20, 30, 40, 50], 60), None);
    println!("All checks passed!");
}

