/// Converts a number to its binary representation as a string without leading zeros.
///
/// # Examples
///
/// ```
/// assert_eq!(to_binary(0), "0");
/// assert_eq!(to_binary(1), "1");
/// assert_eq!(to_binary(2), "10");
/// assert_eq!(to_binary(3), "11");
