/// assert_eq!(to_binary(5), "101");
/// assert_eq!(to_binary(6), "110");
/// assert_eq!(to_binary(7), "111");
/// ```
fn to_binary(n: u32) -> String {
    if n == 0 {
        return "0".to_string();
