/// Converts a Roman numeral to a number.
///
/// # Examples
///
/// ```
/// assert_eq!(from_roman("III"), Some(3));
/// assert_eq!(from_roman("IV"), Some(4));
/// assert_eq!(from_roman("IX"), Some(9));
/// assert_eq!(from_roman("LVIII"), Some(58));
/// assert_eq!(from_roman("XL"), Some(40));
/// assert_eq!(from_roman("XC"), Some(90));
/// assert_eq!(from_roman("CD"), Some(400));
/// assert_eq!(from_roman("CM"), Some(900));
/// assert_eq!(from_roman(""), None);
/// ```
fn from_roman(s: &str) -> Option<u32> {
    if s.len() == 0 {
        return None;
    }

    let mut value = 0;
    let mut i = 0;

    while i < s.len() {
        let current_char = s.chars().nth(i).unwrap();

        match current_char {
            'I' => {
                value += 1;
            }
            'V' => {
                value += 5;
            }
            'X' => {
                value += 10;
            }
            'L' => {
                value += 50;
            }
            'C' => {
                value += 100;
            }
            'D' => {
                value += 500;
            }
            'M' => {
                value += 1000;
            }
            _ => {
                return None; // Invalid character
            }
        }

        i += 1;
    }

    Some(value)
}

