/// Encrypts a string by shifting each letter forward by a specified number of positions.
/// Wraps around the alphabet and maintains case.
///
/// # Examples
///
/// ```
/// assert_eq!(caesar("hello", 5), "lipps");
/// assert_eq!(caesar("world", 10), "asvph");
/// ```
fn caesar(s: &str, shift: u8) -> String {
    s.chars()
        .map(|c| {
            if c.is_ascii_lowercase() {
                // Shift lowercase letters
                ((c as u8 - b'a' + shift) % 26) + b'a'
            } else if c.is_ascii_uppercase() {
                // Shift uppercase letters
                ((c as u8 - b'A' + shift) % 26) + b'A'
            } else {
                // Non-alphabetic characters remain unchanged
                c
            }
        })
        .collect()
}

