/// Checks if the brackets in a string are balanced.
/// 
/// # Examples
/// 
/// ```
/// assert_eq!(is_balanced(String::from("()")), true);
/// assert_eq!(is_balanced(String::from("[]")), true);
/// assert_eq!(is_balanced(String::from("{}")), true);
/// assert_eq!(is_balanced(String::from("(()))")), false);
/// assert_eq!(is_balanced(String::from("[]()")), true);
/// assert_eq!(is_balanced(String::from("{}()")), true);
/// assert_eq!(is_balanced(String::from(")(")), false);
/// ```
fn is_balanced(s: &str) -> bool {
    let mut balance = 0;
    for c in s.chars() {
        if c == '(' {
            balance += 1;
        } else if c == ')' {
            balance -= 1;
        }
        // If balance goes negative, it means there's a closing bracket before an opening one
        if balance < 0 {
            return false;
        }
    }
    // If balance is zero, all brackets are matched correctly
    balance == 0
}

