/// Counts the steps of the Collatz sequence from `n` to 1.
/// An even number is halved, an odd number becomes 3n + 1.
/// The function returns the total number of steps.
///
/// # Examples
///
/// ```
/// assert_eq!(collatz_steps(1), 0);
/// assert_eq!(collatz_steps(5), 5);
/// assert_eq!(collatz_steps(10), 10);
/// ```
fn collatz_steps(n: u64) -> u32 {
    let mut steps = 0;
    while n != 1 {
        if n % 2 == 0 {
            n /= 2;
        } else {
            n = 3 * n + 1;
        }
        steps += 1;
    }
    steps
}

