/// Calculates the median of a slice of f64 numbers.
/// If the slice is empty, returns None.
///
/// # Examples
///
/// ```
/// assert_eq!(median(&[3.0, 1.0, 2.0]), Some(2.0));
/// assert_eq!(median(&[1.0, 2.0, 3.0]), Some(2.5));
/// assert_eq!(median(&[]), None);
/// ```
fn median(v: &[f64]) -> Option<f64> {
    if v.is_empty() {
        return None;
    }

    let mut sorted_v = v.to_vec();
    sorted_v.sort_unstable();

    let len = sorted_v.len();
    let mid = len / 2;

    if len % 2 == 0 {
        Some((sorted_v[mid - 1] + sorted_v[mid]) / 2.0)
    } else {
        Some(sorted_v[mid])
    }
}

