/// Transpose a rectangular matrix.
/// An empty matrix returns an empty matrix.
///
/// # Examples
///
/// ```
/// assert_eq!(transpose(&vec![vec![1, 2], vec![3, 4]]), vec![vec![1, 3], vec![2, 4]]);
/// assert_eq!(transpose(&vec![vec![5], vec![6]]), vec![vec![5], vec![6]]);
/// assert_eq!(transpose(&vec![]), Vec::<Vec<i32>>::new());
/// ```
fn transpose(m: &[Vec<i32>]) -> Vec<Vec<i32>> {
    if m.is_empty() {
        return Vec::<Vec<i32>>::new();
    }

    let mut transposed = Vec::new();
    for (col, row) in m.iter().enumerate() {
        transposed.push(row.into_iter().map(|&val| val).collect());
    }

    transposed
}

