/// Converts a hexadecimal color to RGB values.
/// The function returns None for any invalid input.
///
/// # Examples
///
/// ```
/// assert_eq!(hex_to_rgb("#FF0000"), Some((255, 0, 0)));
/// assert_eq!(hex_to_rgb("#1A3F56"), Some((255, 165, 85)));
/// assert_eq!(hex_to_rgb("#000000"), None);
/// assert_eq!(hex_to_rgb("#1A3F5678"), Some((255, 165, 85)));
/// ```
fn hex_to_rgb(s: &str) -> Option<(u8, u8, u8)> {
    if !s.matches(r"^#([0-9a-fA-F]{2})([0-9a-fA-F]{2})([0-9a-fA-F]{2})$") {
        return None;
    }

    let hex = s.trim();
    let r = u8::from_str_radix(hex, 16).unwrap();
    let g = u8::from_str_radix(hex, 16).unwrap();
    let b = u8::from_str_radix(hex, 16).unwrap();

    Some((r, g, b))
}

