    assert_eq!(hex_to_rgb("#FF0000"), Some((255, 0, 0)));
    assert_eq!(hex_to_rgb("#1A3F56"), Some((255, 165, 85)));
    assert_eq!(hex_to_rgb("#000000"), None);
    assert_eq!(hex_to_rgb("#1A3F5678"), Some((255, 165, 85)));
    println!("All tests passed successfully!");
}

