/// Rotate a vector `v` to the left by `k` positions.
///
/// # Examples
///
/// ```
/// assert_eq!(rotate_left(&[1, 2, 3], 2), &[3, 1, 2]);
/// assert_eq!(rotate_left(&[1, 2, 3], 5), &[1, 2, 3]);
/// assert_eq!(rotate_left(&[], 3), Vec::<i32>::new());
/// ```
fn rotate_left(v: &[i32], k: usize) -> Vec<i32> {
    if v.is_empty() || k == 0 {
        return v.to_vec();
    }

    let k = k % v.len(); // Handle cases where k is greater than the length

    let mut rotated = Vec::with_capacity(v.len());

    for i in 0..v.len() {
        rotated.push(v[(i + k) % v.len()]);
    }

    rotated
}

// Function to check the correctness of the rotate_left function
fn check() {
    assert_eq!(rotate_left(&[1, 2, 3], 2), &[3, 1, 2]);
    assert_eq!(rotate_left(&[1, 2, 3], 5), &[1, 2, 3]);
    assert_eq!(rotate_left(&[], 3), Vec::<i32>::new());
    assert_eq!(rotate_left(&[4, 5, 6, 7], 2), &[7, 4, 5, 6]);
    println!("All tests passed successfully.");
}

