/// Parses a string like "a=1;b=two" into a map.
/// Pairs are separated by ";" and each pair is "key=value".
/// Pairs without "=" are ignored.
///
/// # Examples
///
/// ```
/// assert_eq!(parse_kv("a=1;b=two"), HashMap::from([("a", "1"), ("b", "two")]));
/// assert_eq!(parse_kv("key=value;key2=value3"), HashMap::from([("key", "value"), ("key2", "value3")]));
/// ```
fn parse_kv(s: &str) -> HashMap<String, String> {
    s.split(';')
        .map(|pair| {
            let parts: Vec<&str> = pair.split('=').collect();
            if parts.len() == 2 {
                (parts[0], parts[1])
            } else {
                (String::from(parts[0]), String::from(parts[1]))
            }
        })
        .collect()
}

